START TRANSACTION;

CREATE TEMPORARY TABLE prompt_question_reframes_074 (
    id VARCHAR(64) NOT NULL PRIMARY KEY,
    old_question_en TEXT NOT NULL,
    question_en TEXT NOT NULL,
    question_ko TEXT NOT NULL,
    tip TEXT NOT NULL
);


UPDATE prompts p
JOIN prompt_question_reframes_074 r ON r.id = p.id
SET p.question_en = r.question_en,
    p.question_ko = r.question_ko,
    p.tip = r.tip
WHERE p.is_active = 1
  AND p.question_en = r.old_question_en;

DROP TEMPORARY TABLE prompt_question_reframes_074;

COMMIT;
